def format_date_tuple(date):
    year, month, day = date
    padded_month = month
    padded_day = day
    if year < 1000:
        padded_year, padded_month, padded_day = year, month, day
    elif month < 10:
        padded_month = f'0{month}'
    elif day < 10:
        padded_day = f'0{day}'
    return f'{year}-{padded_month}-{padded_day}'
