def oxford_join_numbers(numbers):
    count = len(numbers)
    if count == 0:
        return ''
    strings = str(n) for n in numbers
    if count <= 2:
        return ' '.join(strings)
    return ", ".join(strings)[:-2] + " and " + strings[-1]
